package com.alibaba.fastjson2;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Type;
import java.util.List;

public class JSONParseObjectTypeWithContextTest {

    public static class User {
        public String name;
        public int age;
    }

    @Test
    public void testNullAndEmptyReturnNull() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = User.class;

        User userNull = JSON.parseObject(null, type, context);
        User userEmpty = JSON.parseObject("", type, context);

        Assertions.assertNull(userNull);
        Assertions.assertNull(userEmpty);
    }

    @Test
    public void testParseSimpleClassWithContext() {
        String json = "{\"name\":\"John\",\"age\":30}";
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = User.class;

        User user = JSON.parseObject(json, type, context);

        Assertions.assertNotNull(user);
        Assertions.assertEquals("John", user.name);
        Assertions.assertEquals(30, user.age);
    }

    @Test
    public void testParseGenericTypeWithContext() {
        String json = "[{\"name\":\"John\",\"age\":30},{\"name\":\"Jane\",\"age\":25}]";
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = new TypeReference<List<User>>() {}.getType();

        List<User> users = JSON.parseObject(json, type, context);

        Assertions.assertNotNull(users);
        Assertions.assertEquals(2, users.size());
        Assertions.assertEquals("John", users.get(0).name);
        Assertions.assertEquals(30, users.get(0).age);
        Assertions.assertEquals("Jane", users.get(1).name);
        Assertions.assertEquals(25, users.get(1).age);
    }

    @Test
    public void testInputNotEndThrowsWithoutIgnoreCheckClose() {
        String json = "{\"name\":\"John\",\"age\":30} trailing";
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = User.class;

        JSONException ex = Assertions.assertThrows(JSONException.class, () -> {
            JSON.parseObject(json, type, context);
        });
        Assertions.assertTrue(ex.getMessage().contains("input not end"));
    }

    @Test
    public void testIgnoreCheckCloseAllowsTrailingContent() {
        String json = "{\"name\":\"John\",\"age\":30} trailing";
        JSONReader.Context context = JSONFactory.createReadContext(JSONReader.Feature.IgnoreCheckClose);
        Type type = User.class;

        User user = JSON.parseObject(json, type, context);

        Assertions.assertNotNull(user);
        Assertions.assertEquals("John", user.name);
        Assertions.assertEquals(30, user.age);
    }
}

